<script setup lang="ts">
import { computed, ref, onUnmounted } from 'vue';
import { Button } from '../ui/button';
import { ChoiceSelect } from '../ui/controls';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../ui/dialog';
import { runtimeRequest, type RuntimeEnvironment, type KernelReleases } from './runtimeApi';

/** 请求内核管理，提交版本独立于列表轮询。 */
const props=defineProps<{environment:RuntimeEnvironment}>();
const emit=defineEmits<{refresh:[];busy:[value:boolean]}>();
type Operation='prepare'|'activate'|'rollback'|'recover';
const labels:Record<Operation,string>={prepare:'准备内核',activate:'激活候选',rollback:'回滚内核',recover:'恢复对账'};
const states:Record<string,string>={idle:'可准备',preparing:'正在下载并校验',draining:'等待在途请求结束',switching:'预热候选',restoring:'恢复原版',finishing:'核对并开放接单',active:'已生效',failed:'保持原版',restored:'已恢复原版',reconcile:'待对账'};
const kernel=computed(()=>props.environment.native_kernel);
const busy=computed(()=>['preparing','draining','switching','restoring','finishing'].includes(kernel.value?.state??''));
const available=computed(()=>!busy.value&&!props.environment.busy&&!!states[kernel.value?.state??'']&&kernel.value?.state!=='reconcile');
const discovery=ref<KernelReleases|null>(null),checking=ref(false),error=ref(''),feedback=ref('');
const action=ref<{operation:Operation;revision:string;digest:string|null;release:string|null;current:string;target:string}|null>(null),release=ref(''),loading=ref(false),sending=ref(false),failed=ref(false),operationError=ref('');
let alive=true,controller:AbortController|undefined,request=0;
const options=computed(()=>(discovery.value?.versions??[]).filter(value=>/^v0\.1\.0-beta\.[1-9][0-9]{0,8}$/.test(value.release)).map(value=>({value:value.release,label:value.release})));
/** 只读发现实际发行版本。@param refresh 强制检查发行源。@return 读取结束。 */
async function check(refresh=true):Promise<void>{const version=++request;controller?.abort();controller=new AbortController();checking.value=true;error.value='';try{const result=await runtimeRequest<KernelReleases>(`/environments/${props.environment.environment_id}/native-kernel/releases${refresh?'?refresh=true':''}`,{signal:controller.signal});if(alive&&version===request)discovery.value=result;}catch(cause){if(alive&&version===request&&(cause as Error).name!=='AbortError')error.value=(cause as Error).message;}finally{if(alive&&version===request)checking.value=false;}}
/** 冻结按钮对应版本，候选列表读取失败保持可取消。@param operation 内核动作。@return 打开结束。 */
async function open(operation:Operation):Promise<void>{const value=kernel.value;if(!value)return;const target=operation==='activate'?value.prepared:operation==='rollback'?value.previous:null;action.value={operation,revision:value.revision,digest:target?.launcher_sha256??null,release:operation==='activate'?target?.release??null:null,current:value.current?.release||'待核对',target:target?.release||(operation==='prepare'?'选择已发布版本后下载并验签':'按服务器持久状态恢复')};failed.value=false;operationError.value='';if(operation==='prepare'){loading.value=true;const original=action.value;await check(false);if(action.value!==original)return;loading.value=false;release.value=options.value[0]?.value??'';if(error.value){failed.value=true;operationError.value=error.value;}}}
/** 提交唯一操作ID和冻结CAS，失联后通过持久状态恢复。@return 操作结束。 */
async function submit():Promise<void>{const value=action.value;if(!value||loading.value||sending.value||failed.value)return;if(value.operation==='prepare'&&!options.value.some(option=>option.value===release.value))return;const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]!&15)|64;bytes[8]=(bytes[8]!&63)|128;const hex=Array.from(bytes,byte=>byte.toString(16).padStart(2,'0')).join('');const operation_id=[hex.slice(0,8),hex.slice(8,12),hex.slice(12,16),hex.slice(16,20),hex.slice(20)].join('-');sending.value=true;emit('busy',true);emit('refresh');try{await runtimeRequest(`/environments/${props.environment.environment_id}/native-kernel`,{method:'POST',body:{operation:value.operation,operation_id,expected_revision:value.revision,expected_sha256:value.digest,release:value.operation==='prepare'?release.value:value.release}});if(!alive)return;action.value=null;feedback.value='内核操作已完成，版本以最新读取状态为准。';}catch(cause){if(alive){failed.value=true;operationError.value=(cause as Error).message+'。请关闭窗口并刷新状态后重新操作。';}}finally{if(alive){sending.value=false;emit('busy',false);emit('refresh');}}}
onUnmounted(()=>{alive=false;request++;controller?.abort();});
</script>
<template>
  <section class="environment-kernel">
    <template v-if="kernel"><div class="kernel-version"><span>当前内核</span><strong>{{ kernel.current?.release||'未提供' }}</strong><span class="environment-state-label">{{ states[kernel.state]||'状态待核对' }}</span></div><div class="workspace-properties"><div class="kv"><span>已准备候选</span><strong>{{ kernel.prepared?.release||'未准备' }}</strong></div><div class="kv"><span>上一版本</span><strong>{{ kernel.previous?.release||'无' }}</strong></div><div class="kv"><span>镜像内置</span><strong>{{ kernel.builtin?.release||'未提供' }}</strong></div></div><p>{{ discovery?.state==='stale'?'版本检查失败，显示上次发现结果。准备时将重新验签。':discovery?.state==='unavailable'?'版本列表暂不可用，当前内核运行保持原状态。':discovery?.latest?`最新发现版本：${discovery.latest}`:'可检查已发布的配套内核版本' }}</p><p v-if="kernel.error||error" role="alert" class="runtime-error">{{ kernel.error||error }}</p><p v-if="environment.busy">CLI 作业执行中，请在空闲后操作内核。</p><div class="workspace-inline-actions"><Button variant="outline" :disabled="busy||checking||sending" @click="check()">{{ checking?'检查中…':'检查更新' }}</Button><Button variant="outline" :disabled="!available||sending" @click="open('prepare')">选择版本</Button><Button :disabled="!available||sending||!kernel.prepared||kernel.prepared.launcher_sha256===kernel.current?.launcher_sha256" @click="open('activate')">激活候选</Button><Button variant="outline" :disabled="!available||sending||!kernel.previous" @click="open('rollback')">回滚内核</Button><Button v-if="kernel.state==='reconcile'" variant="outline" :disabled="busy||environment.busy||sending" @click="open('recover')">恢复对账</Button></div><p v-if="feedback" role="status">{{ feedback }}</p><details class="runtime-technical"><summary>版本摘要与预热回执</summary><dl><dt>当前分发 SHA256</dt><dd><code>{{ kernel.current?.launcher_sha256||'未提供' }}</code></dd><dt>候选分发 SHA256</dt><dd><code>{{ kernel.prepared?.launcher_sha256||'未准备' }}</code></dd><dt>上一版分发 SHA256</dt><dd><code>{{ kernel.previous?.launcher_sha256||'无' }}</code></dd><dt>上次预热回执 PID</dt><dd>{{ kernel.pid??'未采集' }}</dd><dt>实际映像 SHA256</dt><dd><code>{{ kernel.image_sha256||'未采集' }}</code></dd></dl></details></template><p v-else>{{ environment.request_backend==='native293'?'已选择原生运行时，等待环境准备。':'此环境当前未提供在线内核管理。' }}</p>
    <Dialog :open="!!action" @update:open="value=>{if(!value&&!sending)action=null;}"><DialogContent @escape-key-down="event=>{if(sending)event.preventDefault();}" @pointer-down-outside="event=>{if(sending)event.preventDefault();}"><DialogHeader><DialogTitle>{{ action?labels[action.operation]:'' }}</DialogTitle><DialogDescription>{{ environment.name }} · {{ action?.operation==='prepare'?'准备期间当前内核继续接单。准备完成后可单独激活候选。':'等待在途请求结束，完成目标内核预热与身份核验后继续接单。' }}</DialogDescription></DialogHeader><p>当前版本：{{ action?.current }}</p><p>目标版本：{{ action?.target }}</p><ChoiceSelect v-if="action?.operation==='prepare'" v-model="release" label="已发布版本" :options="options" :disabled="loading||sending||failed" /><p v-if="loading" role="status">正在读取已发布版本…</p><p v-else-if="action?.operation==='prepare'&&!options.length">暂无可选择版本，请关闭后检查更新。</p><p v-if="operationError" role="alert" class="runtime-error">{{ operationError }}</p><div class="runtime-dialog-actions"><Button variant="outline" :disabled="sending" @click="action=null">取消</Button><Button :disabled="sending||loading||failed||(action?.operation==='prepare'&&!release)" @click="submit">{{ sending?'操作进行中…':action?labels[action.operation]:'确认操作' }}</Button></div></DialogContent></Dialog>
  </section>
</template>
